<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    background: #1a1a2e;
    color: #eee;
    font-family: Arial, Helvetica, sans-serif;
    height: 100%;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
  }
  h1 { margin: 10px 0; }
  #header {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 20px;
  }
  #scorebox {
    background: #16213e;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 18px;
  }
  #score { font-weight: bold; font-size: 24px; }
  #reset {
    background: #0f3460;
    color: #eee;
    border: none;
    padding: 12px 20px;
    border-radius: 8px;
    font-size: 16px;
    cursor: pointer;
  }
  #reset:hover { background: #e94560; }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 90px);
    grid-template-rows: repeat(4, 90px);
    gap: 10px;
    background: #16213e;
    padding: 10px;
    border-radius: 10px;
  }
  .cell {
    display: flex;
    align-items: center;
    justify-content: center;
    background: #0f3460;
    border-radius: 6px;
    font-size: 32px;
    font-weight: bold;
    color: #eee;
  }
  .cell[data-v="0"] { color: transparent; }
  .cell[data-v="2"] { background: #3d5a80; }
  .cell[data-v="4"] { background: #4a6fa5; }
  .cell[data-v="8"] { background: #e9a05b; }
  .cell[data-v="16"] { background: #f08a5d; color:#fff; }
  .cell[data-v="32"] { background: #f07b3f; color:#fff; }
  .cell[data-v="64"] { background: #ea5455; color:#fff; }
  .cell[data-v="128"] { background: #d65a31; color:#fff; font-size:28px; }
  .cell[data-v="256"] { background: #c1440e; color:#fff; font-size:28px; }
  .cell[data-v="512"] { background: #b83b5e; color:#fff; font-size:28px; }
  .cell[data-v="1024"] { background: #6a2c70; color:#fff; font-size:22px; }
  .cell[data-v="2048"] { background: #f9ed69; color:#333; font-size:22px; }
</style>
</head>
<body>
  <h1>2048</h1>
  <div id="header">
    <div id="scorebox">Score: <span id="score">0</span></div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>

<script>
(function() {
  const SIZE = 4;
  let grid = [];
  let scoreVal = 0;

  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const resetBtn = document.getElementById('reset');

  function emptyGrid() {
    const g = [];
    for (let r = 0; r < SIZE; r++) {
      g.push(new Array(SIZE).fill(0));
    }
    return g;
  }

  function render() {
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = grid[r][c];
        const div = document.createElement('div');
        div.className = 'cell';
        div.setAttribute('data-v', v);
        div.textContent = v === 0 ? '' : v;
        boardEl.appendChild(div);
      }
    }
    scoreEl.textContent = scoreVal;
  }

  function emptyCells() {
    const cells = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) cells.push([r, c]);
      }
    }
    return cells;
  }

  function spawn() {
    const cells = emptyCells();
    if (cells.length === 0) return;
    const [r, c] = cells[Math.floor(Math.random() * cells.length)];
    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
  }

  // slide+merge a single row to the left; returns {row, gained}
  function slideRow(row) {
    const filtered = row.filter(v => v !== 0);
    const result = [];
    let gained = 0;
    let i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        const merged = filtered[i] * 2;
        result.push(merged);
        gained += merged;
        i += 2;
      } else {
        result.push(filtered[i]);
        i += 1;
      }
    }
    while (result.length < SIZE) result.push(0);
    return { row: result, gained };
  }

  function equalGrid(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  function move(dir) {
    const before = grid.map(row => row.slice());
    let gained = 0;

    if (dir === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const res = slideRow(grid[r]);
        grid[r] = res.row;
        gained += res.gained;
      }
    } else if (dir === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const rev = grid[r].slice().reverse();
        const res = slideRow(rev);
        grid[r] = res.row.reverse();
        gained += res.gained;
      }
    } else if (dir === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = 0; r < SIZE; r++) col.push(grid[r][c]);
        const res = slideRow(col);
        for (let r = 0; r < SIZE; r++) grid[r][c] = res.row[r];
        gained += res.gained;
      }
    } else if (dir === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = 0; r < SIZE; r++) col.push(grid[r][c]);
        col.reverse();
        const res = slideRow(col);
        const newCol = res.row.reverse();
        for (let r = 0; r < SIZE; r++) grid[r][c] = newCol[r];
        gained += res.gained;
      }
    } else {
      return false;
    }

    const changed = !equalGrid(before, grid);
    if (changed) {
      scoreVal += gained;
      spawn();
      render();
    }
    return changed;
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    spawn();
    spawn();
    render();
  }

  function setBoard(arr) {
    grid = emptyGrid();
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        grid[r][c] = (arr[r] && arr[r][c]) ? arr[r][c] : 0;
      }
    }
    render();
  }

  document.addEventListener('keydown', function(e) {
    let dir = null;
    switch (e.key) {
      case 'ArrowLeft': dir = 'left'; break;
      case 'ArrowRight': dir = 'right'; break;
      case 'ArrowUp': dir = 'up'; break;
      case 'ArrowDown': dir = 'down'; break;
    }
    if (dir) {
      e.preventDefault();
      move(dir);
    }
  });

  resetBtn.addEventListener('click', reset);

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: function() { return grid.map(row => row.slice()); },
    setBoard: setBoard,
    score: function() { return scoreVal; }
  };

  reset();
})();
</script>
</body>
</html>
